use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let matrix = input.as_array().unwrap();
    let mut transposed = Vec::new();
    for row in matrix {
        let mut row_values = Vec::new();
        for col in row {
            row_values.push(col.as_i64().unwrap());
        }
        transposed.push(Value::from(row_values));
    }
    Value::from(transposed)
}
